lessons.solution:
func ReverseRunes(s string) string {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	return string(r)
}

func LastWord(s string) string {
	words := strings.Fields(s)
	if len(words) == 0 {
		return ""
	}
	return words[len(words)-1]
}

func ReplaceFirst(values []int, x int) []int {
	out := append([]int{}, values...)
	if len(out) > 0 {
		out[0] = x
	}
	return out
}

func Positive(values []int) []int {
	out := []int{}
	for _, n := range values {
		if n > 0 {
			out = append(out, n)
		}
	}
	return out
}

func Chunks(values []int, size int) [][]int {
	out := [][]int{}
	if size <= 0 {
		return out
	}
	for start := 0; start < len(values); start += size {
		end := start + size
		if end > len(values) {
			end = len(values)
		}
		out = append(out, append([]int{}, values[start:end]...))
	}
	return out
}

