func CountRune(s string, wanted rune) int {
	count := 0
	for _, r := range s {
		if r == wanted {
			count++
		}
	}
	return count
}

func Unique(s string) string {
	seen := map[rune]bool{}
	out := []rune{}
	for _, r := range s {
		if !seen[r] {
			seen[r] = true
			out = append(out, r)
		}
	}
	return string(out)
}

