lessons.solution:
func Prime(n int) bool {
	if n < 2 {
		return false
	}
	for d := 2; d <= n/d; d++ {
		if n%d == 0 {
			return false
		}
	}
	return true
}

func Factorial(n int) int {
	if n <= 1 {
		return 1
	}
	return n * Factorial(n-1)
}

func PrimeSum(n int) int {
	total := 0
	for k := 2; k <= n; k++ {
		prime := true
		for d := 2; d <= k/d; d++ {
			if k%d == 0 {
				prime = false
				break
			}
		}
		if prime {
			total += k
		}
	}
	return total
}
